# -----------------------------------------------------------------------------
# Helpers
# -----------------------------------------------------------------------------
def b(v) -> bool:
    """Converte colunas heterogêneas para booleano com segurança."""
    if isinstance(v, bool):
        return v
    if pd.isna(v):
        return False
    return str(v).strip().lower() in {"true", "1", "sim", "yes", "y"}


QAQC_LABELS = {
    "Conforme": "Conforme",
    "Acompanhar": "Acompanhar",
    "Revisão recomendada": "Revisão recomendada",
    "Sem atualização recente": "Sem atualização recente",
}

RECEBIMENTO_LABELS = {
    "RECEBENDO": "Conforme",
    "SEM ATUALIZAÇÃO RECENTE": "Sem atualização recente",
}


def normalizar_instrumento(value: object) -> str:
    return "".join(str(value or "").split()).upper()


def carregar_contextos_instrumentos() -> dict[str, dict[str, str]]:
    """Carrega exceções de contexto sem interferir nos cálculos técnicos."""
    if not CONTEXTO_INSTRUMENTOS_PATH.exists():
        return {}
    contexto = pd.read_csv(CONTEXTO_INSTRUMENTOS_PATH, dtype=str).fillna("")
    return {
        normalizar_instrumento(row["instrumento"]): {
            "categoria": str(row.get("categoria", "")),
            "descricao": str(row.get("descricao", "")),
        }
        for _, row in contexto.iterrows()
        if normalizar_instrumento(row.get("instrumento", ""))
    }


CONTEXTOS_INSTRUMENTOS = carregar_contextos_instrumentos()

DELTA_COTA_AJUDA = (
    "Δ Cota compara a cota atual representativa com a referência do próprio instrumento. "
    "Fórmula: cota atual representativa − cota de referência. Exemplo: 100,0 m − 101,2 m = −1,2 m; "
    "a cota atual está 1,2 m mais baixa. Negativo indica redução, positivo indica elevação e valores "
    "entre −0,10 m e +0,10 m são considerados estáveis. O valor descreve a variação, não a causa. "
    "O símbolo — indica comparação não calculada."
)

QAQC_AJUDA = (
    "O QA/QC avalia a confiabilidade do dado, sem interpretar a causa hidrogeológica. "
    "Conforme: sem sinal técnico relevante; Acompanhar: sinal que pede observação; "
    "Revisão: dado que requer checagem técnica; Sem atualização: não há leitura recente suficiente. "
    "São consideradas atualização, consistência recente, flatline e mudanças não confirmadas."
)

REFERENCIA_AJUDA = (
    "Valor válido mais próximo da data-alvo do período. A busca admite até ±14 dias para "
    "monitoramento automático e até ±30 dias para manual. Sem valor válido nessa janela, "
    "a comparação fica como —."
)

SERIE_HISTORICA_AJUDA = (
    "Mostra as leituras manuais e automáticas disponíveis. A linha de cota atual representa o "
    "valor aceito para a comparação; a linha de referência mostra o valor válido usado no período."
)


def instrumento_ambiental(value: object) -> bool:
    contexto = CONTEXTOS_INSTRUMENTOS.get(normalizar_instrumento(value), {})
    return contexto.get("categoria") == "ACOMPANHAMENTO_AMBIENTAL"


def classificar_condicionante_icmbio(row: pd.Series) -> str:
    """Aplica somente o destaque institucional; não altera QA/QC nem cálculos."""
    status = str(row.get("status_qaqc", ""))
    atual = pd.to_numeric(row.get("cota_atual_representativa_m"), errors="coerce")
    delta_12m = pd.to_numeric(row.get("delta_12m_m"), errors="coerce")
    delta_90d = pd.to_numeric(row.get("delta_90d_m"), errors="coerce")
    if status == "Sem atualização recente" or pd.isna(atual) or (pd.isna(delta_12m) and pd.isna(delta_90d)):
        return "Alerta · sem confirmação"
    if (pd.notna(delta_12m) and float(delta_12m) < -0.10) or (
        pd.notna(delta_90d) and float(delta_90d) < -0.10
    ):
        return "Alerta · redução de cota"
    return "Alerta · monitoramento prioritário"


def qaqc_label(value: object) -> str:
    return QAQC_LABELS.get(str(value), str(value))


def recebimento_label(value: object) -> str:
    return RECEBIMENTO_LABELS.get(str(value), str(value))


def texto_qaqc(value: object) -> str:
    return str(value or "")


def numero_pt(value: object, casas: int = 2, *, sinal: bool = False) -> str:
    numero = pd.to_numeric(value, errors="coerce")
    if pd.isna(numero):
        return "—"
    formato = f"{{:{'+' if sinal else ''}.{casas}f}}"
    return formato.format(float(numero)).replace("-", "−").replace(".", ",")


def texto_qaqc_curto(row: pd.Series) -> str:
    """Resume o sinal atual para a visão inicial de confiabilidade."""
    status = str(row.get("status_qaqc", ""))
    texto = texto_qaqc(row.get("motivos", ""))
    if "permaneceram constantes" in texto:
        return "Leituras consecutivas constantes"
    if status == "Sem atualização recente":
        return "Sem atualização recente"
    resumo = texto.split("—", 1)[-1].strip().rstrip(".")
    return resumo if resumo else "Consultar detalhes do instrumento"


def localidade_publica(value: object) -> str:
    """Apresenta os nomes de localização na linguagem institucional."""
    texto = str(value or "—").strip()
    nomes = {
        "alegria norte": "Setor Norte",
        "alegria sul": "Setor Sul",
        "cava germano": "Complexo Germano",
        "joao manoel": "João Manoel",
        "conta historia": "Conta História",
    }
    return nomes.get(texto.casefold(), texto)


def ultimo_dado_publico(row: pd.Series) -> str:
    """Combina valor e data para leitura rápida por públicos não técnicos."""
    valor = pd.to_numeric(row.get("ultima_leitura_cota_m"), errors="coerce")
    data = pd.to_datetime(row.get("ultima"), errors="coerce")
    valor_txt = f"{numero_pt(valor)} m" if pd.notna(valor) else "valor não disponível"
    data_txt = data.strftime("%d/%m/%Y") if pd.notna(data) else "data não disponível"
    if pd.isna(valor) and pd.isna(data):
        return "Sem registro disponível"
    return f"{valor_txt} · {data_txt}"


def explicar_situacao_instrumento(
    row: pd.Series,
    delta_col: str,
    referencia_col: str,
    periodo: str,
) -> tuple[str, str, str]:
    """Traduz o diagnóstico técnico em situação, significado e ação."""
    sinais = {
        item.strip()
        for item in str(row.get("sinais_qaqc", "") or "").split("|")
        if item.strip()
    }
    status = str(row.get("status_qaqc", "") or "")
    atual = pd.to_numeric(row.get("cota_atual_representativa_m"), errors="coerce")
    referencia = pd.to_numeric(row.get(referencia_col), errors="coerce")
    delta = pd.to_numeric(row.get(delta_col), errors="coerce")

    if status == "Sem atualização recente":
        dias_sem = pd.to_numeric(row.get("dias_sem_leitura"), errors="coerce")
        modo = str(row.get("modo_monitoramento", "") or "")
        if pd.notna(dias_sem):
            dias = int(dias_sem)
            tempo = f"A última leitura disponível ocorreu há {dias} dia{'s' if dias != 1 else ''}. "
        else:
            tempo = "Não foi possível confirmar uma leitura atual. "
        if modo == "Automático":
            acao = "Confirmar o recebimento automático dos dados e a condição operacional do instrumento."
        elif modo == "Manual":
            acao = "Confirmar a data prevista da próxima campanha de medição manual."
        else:
            acao = "Confirmar a situação atual do ponto e se haverá nova atualização do histórico."
        return (
            "Sem leitura recente",
            tempo + "O valor continua visível apenas como histórico, mas não representa a condição atual e não entra no cálculo da variação da cota.",
            acao,
        )
    if "conflito_temporal" in sinais:
        return (
            "Leituras diferentes no mesmo horário",
            "Foram registrados valores de cota diferentes para a mesma data e hora. Esses registros não são escolhidos automaticamente nem entram no cálculo.",
            "Conferir qual registro deve permanecer e atualizar a base.",
        )
    if "mudanca_referencia" in sinais:
        salto = pd.to_numeric(row.get("salto_cota_boca_m"), errors="coerce")
        detalhe = f" A cota de boca mudou {numero_pt(abs(float(salto)))} m." if pd.notna(salto) else ""
        return (
            "Cota de boca alterada",
            "A referência altimétrica do instrumento foi alterada." + detalhe +
            " O degrau observado na série reflete a mudança de referência, não variação do nível d'água.",
            "Confirmar o novo levantamento de boca e verificar se o histórico precisa ser reprocessado.",
        )
    if "profundidade_cadastro_suspeita" in sinais:
        return (
            "Profundidade cadastrada incompatível com a série",
            "Boa parte das leituras deste instrumento fica abaixo da profundidade registrada no "
            "cadastro. Nesse caso o dado divergente é o cadastro, não a medição, e nenhuma leitura "
            "foi descartada do cálculo.",
            "Conferir a profundidade cadastrada do furo junto à base de cadastro.",
        )
    if "fora_faixa_fisica" in sinais:
        return (
            "Leitura fora da faixa física",
            "Há registros incompatíveis com a geometria do instrumento: nível acima da boca do tubo ou "
            "abaixo do fundo do furo. Leituras abaixo do fundo não entram no cálculo.",
            "Conferir os registros destacados e a profundidade cadastrada do furo.",
        )
    if "salto_manual_nao_confirmado" in sinais:
        return (
            "Campanha manual fora do padrão",
            "A campanha manual mais recente ficou distante do comportamento habitual do instrumento e "
            "ainda não há campanha posterior que a confirme. Ela não é usada como condição atual.",
            "Conferir a leitura em campo e o registro na base antes da próxima campanha.",
        )
    if "salto_manual_isolado" in sinais:
        return (
            "Campanha manual isolada fora do padrão",
            "Uma campanha ficou fora do padrão e as seguintes retornaram ao regime anterior. Ela não "
            "redefine, sozinha, a condição atual.",
            "Conferir o registro destacado e manter o acompanhamento das campanhas.",
        )
    if "patamar_manual_nao_confirmado" in sinais:
        return (
            "Mudança de nível ainda sem confirmação nas campanhas",
            "As campanhas manuais mudaram de nível e ainda não há campanhas posteriores suficientes "
            "para confirmar o novo patamar.",
            "Acompanhar as próximas campanhas antes de considerar o novo nível como representativo.",
        )
    if "divergencia_vizinhanca" in sinais:
        return (
            "Variação diferente da vizinhança",
            "A variação deste instrumento difere do comportamento dos pontos em raio de 250 m, sem "
            "PTR ativo próximo que explique a diferença.",
            "Comparar o histórico com os pontos vizinhos e confirmar a consistência do registro.",
        )
    if "flatline" in sinais:
        return (
            "Possível travamento das leituras (flatline)",
            "O mesmo valor foi registrado exatamente em pelo menos cinco datas consecutivas. Enquanto essa repetição persistir, a cota atual não é usada na comparação.",
            "Conferir a aquisição das leituras e aguardar pelo menos três novos valores coerentes e não idênticos.",
        )
    if "pos_flatline" in sinais:
        return (
            "Leituras voltaram a variar após período constante",
            "A repetição prolongada terminou, mas ainda não existem três novas leituras coerentes e diferentes para confirmar a condição atual.",
            "Acompanhar a série até completar três novas leituras coerentes.",
        )
    if "patamar_nao_confirmado" in sinais:
        oscilacao = " Também foi observada oscilação maior que a habitual." if "ruido_elevado" in sinais else ""
        return (
            "Mudança recente ainda sem confirmação",
            "As leituras mudaram para um novo nível, mas ainda não há três leituras posteriores coerentes para confirmar esse novo patamar." + oscilacao,
            "Acompanhar as próximas leituras antes de considerar o novo nível como representativo.",
        )
    if "salto_nao_confirmado" in sinais:
        return (
            "Última leitura muito diferente das anteriores",
            "A leitura mais recente ficou distante do comportamento habitual e ainda não há dados posteriores suficientes para confirmar se ela representa uma nova condição.",
            "Conferir o registro e acompanhar as próximas leituras.",
        )
    if "salto_isolado" in sinais:
        return (
            "Leitura isolada do padrão (possível outlier)",
            "Uma leitura ficou muito diferente do comportamento habitual e as leituras seguintes retornaram ao padrão anterior. Ela não redefine, sozinha, a condição atual.",
            "Conferir o registro destacado e manter o acompanhamento da série.",
        )
    if "ruido_elevado" in sinais:
        return (
            "Oscilação recente maior que a habitual",
            "As leituras recentes alternam mais do que o histórico do próprio instrumento. A condição atual pode precisar de novas leituras para ficar representativa.",
            "Conferir a aquisição e acompanhar a continuidade da série.",
        )
    if pd.isna(atual):
        return (
            "Sem cota atual representativa",
            "As leituras disponíveis ainda não atendem aos critérios de quantidade e consistência usados para representar a condição atual.",
            "Consultar os detalhes de confiabilidade e acompanhar novas leituras.",
        )
    if pd.isna(referencia):
        modo = str(row.get("modo_monitoramento", "") or "")
        tolerancia = "14 dias" if modo == "Automático" else "30 dias"
        return (
            f"Sem referência de {periodo.lower()}",
            f"Existe uma cota atual, mas não há medição válida suficientemente próxima da data de comparação. A tolerância usada para este instrumento é de {tolerancia}.",
            "Manter o instrumento visível e registrar que este período não pode ser comparado.",
        )
    if pd.isna(delta):
        return (
            "Comparação não calculada",
            "A cota atual ou a referência do período não ficou disponível após as verificações de consistência. O traço em Δ Cota não representa valor zero.",
            "Consultar os detalhes do instrumento para identificar qual informação está ausente.",
        )
    if float(delta) < -0.10:
        return (
            "Cota atual abaixo da referência",
            f"A cota representativa atual está {numero_pt(abs(float(delta)))} m abaixo da referência de {periodo.lower()}.",
            "Avaliar o comportamento junto ao histórico, aos pontos vizinhos e ao contexto operacional.",
        )
    if float(delta) > 0.10:
        return (
            "Cota atual acima da referência",
            f"A cota representativa atual está {numero_pt(abs(float(delta)))} m acima da referência de {periodo.lower()}.",
            "Avaliar o comportamento junto ao histórico, aos pontos vizinhos e ao contexto operacional.",
        )
    return (
        "Cota próxima da referência",
        f"A diferença entre a cota atual e a referência de {periodo.lower()} está dentro da faixa de comportamento estável (±0,10 m).",
        "Manter o acompanhamento rotineiro.",
    )


def image_data_uri(path: Path) -> str:
    if not path.exists():
        return ""
    mime = "image/png" if path.suffix.lower() == ".png" else "image/jpeg"
    return f"data:{mime};base64,{base64.b64encode(path.read_bytes()).decode('ascii')}"


def brand_header() -> None:
    logo_uri = image_data_uri(SAMARCO_LOGO)
    logo_html = f'<img class="brand-logo" src="{logo_uri}" alt="Samarco">' if logo_uri else ""
    if st.session_state.get("hga_upload_active"):
        data_sessao = pd.to_datetime(st.session_state.get("hga_upload_data_corte"), errors="coerce")
        contexto_base = (
            f"HGA · atualizada até {data_sessao.strftime('%d/%m/%Y')}"
            if pd.notna(data_sessao)
            else "HGA · base da sessão"
        )
    else:
        contexto_base = "HGA · atualizada até 27/08/2026"
    st.markdown(
        f"""
        <div class="brand-header">
            <div>
                <div class="brand-product">HidroCheck</div>
                <div class="brand-tagline">Monitoramento hidrogeológico · Complexo Germano</div>
            </div>
            <div class="brand-right">
                {logo_html}
                <div class="brand-context">{contexto_base}</div>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def section(kicker: str, title: str) -> None:
    kicker_html = (
        ""
        if kicker.strip().casefold() == title.strip().casefold()
        else f'<div class="section-kicker">{kicker}</div>'
    )
    st.markdown(
        f'{kicker_html}<div class="section-title">{title}</div>',
        unsafe_allow_html=True,
    )


def heading_with_help(title: str, help_text: str) -> None:
    st.markdown(
        f'<div class="inline-heading">{html_lib.escape(title)}'
        f'<span class="term-help" title="{html_lib.escape(help_text, quote=True)}">?</span></div>',
        unsafe_allow_html=True,
    )


def kpi_cards(items: list[tuple[str, ...]]) -> None:
    html = '<div class="kpi-grid">'
    for item in items:
        label, value, detail, cls, *help_values = item
        ajuda = help_values[0] if help_values else ""
        ajuda_html = (
            f' <span class="term-help" title="{html_lib.escape(ajuda, quote=True)}">?</span>'
            if ajuda else ""
        )
        html += (
            f'<div class="kpi {cls}">'
            f'<div class="label">{html_lib.escape(label)}{ajuda_html}</div>'
            f'<div class="value">{html_lib.escape(value)}</div>'
            + (f'<div class="detail">{html_lib.escape(detail)}</div>' if detail else "")
            + '</div>'
        )
    html += '</div>'
    st.markdown(html, unsafe_allow_html=True)


def readable_table(
    df: pd.DataFrame,
    *,
    height: int,
    column_widths: list[float],
    min_width: int = 980,
) -> None:
    """Exibe tabelas extensas com quebra de texto e cabeçalho fixo."""
    if df.empty:
        return
    if len(column_widths) != len(df.columns):
        raise ValueError("Uma largura deve ser informada para cada coluna da tabela.")
    total = sum(column_widths) or 1
    colgroup = "<colgroup>" + "".join(
        f'<col style="width:{(width / total) * 100:.2f}%">' for width in column_widths
    ) + "</colgroup>"
    table_html = df.to_html(
        index=False,
        escape=True,
        border=0,
        classes="hc-readable-table",
        na_rep="—",
    )
    table_html = table_html.replace("<table ", f'<table style="min-width:{int(min_width)}px" ', 1)
    table_html = table_html.replace("<thead>", f"{colgroup}<thead>", 1)
    st.markdown(
        f'<div class="hc-table-wrap" style="max-height:{int(height)}px">{table_html}</div>',
        unsafe_allow_html=True,
    )


def sector_card(nome: str, delta: float | None) -> str:
    if delta is None or pd.isna(delta):
        return (
            '<div class="sector-card">'
            f'<div class="name">{nome}</div>'
            '<div class="rate neutral">—</div>'
            '<div class="meaning neutral">sem comparação</div>'
            '</div>'
        )
    if delta < -0.10:
        cls, meaning = "negative", "redução da cota"
    elif delta > 0.10:
        cls, meaning = "positive", "elevação da cota"
    else:
        cls, meaning = "neutral", "estável"
    sinal = "+" if delta > 0 else ""
    return (
        '<div class="sector-card">'
        f'<div class="name">{nome}</div>'
        f'<div class="rate {cls}">{sinal}{delta:.2f} <span style="font-size:.85rem;font-weight:650">m</span></div>'
        f'<div class="meaning {cls}">{meaning}</div>'
        '</div>'
    )


def plot_clean(fig: go.Figure, height: int | None = None) -> go.Figure:
    # Cores explícitas para manter os gráficos legíveis mesmo quando o navegador
    # ou o Streamlit estiverem em tema escuro.
    fig.update_layout(
        paper_bgcolor="#FFFFFF",
        plot_bgcolor="#FFFFFF",
        font=dict(family="Segoe UI, Arial", color="#17212B", size=12),
        margin=dict(l=24, r=24, t=28, b=24),
        legend_title_text="",
        legend=dict(font=dict(color="#17212B", size=12), bgcolor="rgba(255,255,255,0.92)"),
    )
    if height:
        fig.update_layout(height=height)
    axis_style = dict(
        showgrid=True,
        gridcolor="#DDE5EC",
        zeroline=False,
        linecolor="#94A3B8",
        tickfont=dict(color="#334155", size=12),
        title_font=dict(color="#334155", size=13),
    )
    fig.update_xaxes(**axis_style)
    fig.update_yaxes(**axis_style)
    return fig


def _ticks_utm(vmin: float, vmax: float, passo: int) -> tuple[list[int], list[str]]:
    """Coordenadas UTM completas, sem abreviações k ou M."""
    inicio = int(vmin // passo) * passo
    fim = int((vmax // passo) + 1) * passo
    valores = [
        valor for valor in range(inicio, fim + passo, passo)
        if valor >= vmin - passo * 0.20 and valor <= vmax + passo * 0.20
    ]
    return valores, [f"{int(valor):,}".replace(",", ".") for valor in valores]


def _intervalo_mapa(
    x_values: pd.Series,
    y_values: pd.Series,
    rede_completa: bool,
) -> tuple[list[float], list[float]]:
    """Retorna o foco da mina ou a extensão integral das camadas exibidas."""
    if not rede_completa:
        return (
            [FOCO_MINA_BOUNDS["xmin"], FOCO_MINA_BOUNDS["xmax"]],
            [FOCO_MINA_BOUNDS["ymin"], FOCO_MINA_BOUNDS["ymax"]],
        )
    xs = pd.to_numeric(pd.Series(x_values), errors="coerce").dropna()
    ys = pd.to_numeric(pd.Series(y_values), errors="coerce").dropna()
    if xs.empty or ys.empty:
        return (
            [BASE_AEREA_BOUNDS["xmin"], BASE_AEREA_BOUNDS["xmax"]],
            [BASE_AEREA_BOUNDS["ymin"], BASE_AEREA_BOUNDS["ymax"]],
        )
    # A visualização integral nunca deve ficar mais fechada que o foco inicial.
    # Isso evita que o comando "Ver rede completa" pareça aproximar o mapa
    # quando a camada filtrada estiver concentrada em uma parte da mina.
    xmin = min(float(xs.min()), FOCO_MINA_BOUNDS["xmin"])
    xmax = max(float(xs.max()), FOCO_MINA_BOUNDS["xmax"])
    ymin = min(float(ys.min()), FOCO_MINA_BOUNDS["ymin"])
    ymax = max(float(ys.max()), FOCO_MINA_BOUNDS["ymax"])
    xspan = max(xmax - xmin, 1000.0)
    yspan = max(ymax - ymin, 1000.0)
    xpad = max(xspan * 0.055, 300.0)
    ypad = max(yspan * 0.055, 300.0)
    return (
        [xmin - xpad, xmax + xpad],
        [ymin - ypad, ymax + ypad],
    )


def _aplicar_cartografia_mapa(
    fig: go.Figure,
    x_values: pd.Series,
    y_values: pd.Series,
    *,
    rede_completa: bool,
    height: int,
    uirevision: str,
) -> go.Figure:
    """Aplica cartografia sóbria sobre a própria imagem aérea."""
    xr, yr = _intervalo_mapa(x_values, y_values, rede_completa)

    eixo = dict(
        showgrid=False,
        zeroline=False,
        showline=False,
        ticks="",
        ticklabelposition="inside",
        tickfont=dict(color="#FFFFFF", size=11, family="Segoe UI, Arial"),
        title_text="",
        fixedrange=False,
    )
    # Ticks automáticos acompanham o zoom. A barra cartográfica é inserida no
    # navegador e recalculada a cada evento de zoom/pan pelo renderizador abaixo.
    fig.update_xaxes(range=xr, tickmode="auto", nticks=10, tickformat=".0f", **eixo)
    fig.update_yaxes(
        range=yr,
        tickmode="auto",
        nticks=10,
        tickformat=".0f",
        scaleanchor="x",
        scaleratio=1,
        **eixo,
    )
    fig.add_annotation(
        x=0.025, y=0.965, xref="paper", yref="paper",
        text="<b>N</b><br><span style='font-size:24px'>▲</span>",
        showarrow=False, align="center",
        font=dict(color="#FFFFFF", size=13, family="Segoe UI, Arial"),
    )
    fig.add_annotation(
        x=0.992, y=0.015, xref="paper", yref="paper",
        text="SIRGAS 2000 / UTM 23S", showarrow=False,
        xanchor="right", yanchor="bottom",
        font=dict(color="#FFFFFF", size=9, family="Segoe UI, Arial"),
    )
    fig.update_layout(
        height=height,
        paper_bgcolor="#08263B",
        plot_bgcolor="#08263B",
        font=dict(family="Segoe UI, Arial", color="#FFFFFF", size=12),
        margin=dict(l=0, r=0, t=0, b=0),
        dragmode="pan",
        hovermode="closest",
        hoverlabel=dict(bgcolor="#FFFFFF", font_color="#1D2935", font_size=12),
        uirevision=uirevision,
    )
    return fig


def mapa_com_escala_dinamica(fig: go.Figure, *, key: str, height: int) -> None:
    """Renderiza o Plotly offline e mantém a escala ancorada à área visível."""
    post_script = r"""
    (function () {
        const grafico = document.getElementById('{plot_id}');
        let atualizandoEscala = false;

        function valorAgradavel(alvo) {
            if (!Number.isFinite(alvo) || alvo <= 0) return 1000;
            const potencia = Math.pow(10, Math.floor(Math.log10(alvo)));
            const opcoes = [1, 2, 5, 10].map(v => v * potencia);
            let escolhido = opcoes[0];
            opcoes.forEach(v => { if (v <= alvo) escolhido = v; });
            return escolhido;
        }

        function rotuloDistancia(metros) {
            let texto;
            if (metros >= 1000) {
                const km = metros / 1000;
                texto = (km >= 10 ? km.toFixed(0) : km.toFixed(1)) + ' km';
            } else if (metros >= 1) {
                texto = (metros >= 10 ? metros.toFixed(0) : metros.toFixed(1)) + ' m';
            } else {
                texto = metros.toFixed(2) + ' m';
            }
            return texto.replace('.', ',');
        }

        function atualizarEscala() {
            if (atualizandoEscala || !grafico._fullLayout) return;
            const xr = grafico._fullLayout.xaxis.range;
            const yr = grafico._fullLayout.yaxis.range;
            if (!xr || !yr) return;

            const xMin = Math.min(xr[0], xr[1]);
            const xMax = Math.max(xr[0], xr[1]);
            const yMin = Math.min(yr[0], yr[1]);
            const yMax = Math.max(yr[0], yr[1]);
            const xSpan = xMax - xMin;
            const ySpan = yMax - yMin;
            const comprimento = valorAgradavel(xSpan * 0.18);
            const x0 = xMin + xSpan * 0.035;
            const y0 = yMin + ySpan * 0.045;
            const altura = ySpan * 0.014;
            const segmentos = 4;

            const formasBase = (grafico.layout.shapes || []).filter(
                item => item.name !== 'escala-dinamica'
            );
            const anotacoesBase = (grafico.layout.annotations || []).filter(
                item => item.name !== 'rotulo-escala-dinamica'
            );
            const formasEscala = [];
            for (let i = 0; i < segmentos; i += 1) {
                formasEscala.push({
                    type: 'rect', xref: 'x', yref: 'y',
                    x0: x0 + i * comprimento / segmentos,
                    x1: x0 + (i + 1) * comprimento / segmentos,
                    y0: y0, y1: y0 + altura,
                    fillcolor: i % 2 ? '#FFFFFF' : '#111820',
                    line: {color: '#FFFFFF', width: 1},
                    layer: 'above', name: 'escala-dinamica'
                });
            }
            const rotulo = {
                x: x0 + comprimento + xSpan * 0.012,
                y: y0 + altura / 2,
                xref: 'x', yref: 'y',
                text: rotuloDistancia(comprimento),
                showarrow: false, xanchor: 'left', yanchor: 'middle',
                font: {color: '#FFFFFF', size: 11, family: 'Segoe UI, Arial'},
                name: 'rotulo-escala-dinamica'
            };

            atualizandoEscala = true;
            Plotly.relayout(grafico, {
                shapes: formasBase.concat(formasEscala),
                annotations: anotacoesBase.concat([rotulo])
            }).finally(() => { atualizandoEscala = false; });
        }

        grafico.on('plotly_relayout', function () {
            if (!atualizandoEscala) window.requestAnimationFrame(atualizarEscala);
        });
        window.requestAnimationFrame(atualizarEscala);
    })();
    """
    div_id = "hidrocheck-" + "".join(ch if ch.isalnum() or ch in "-_" else "-" for ch in key)
    html = pio.to_html(
        fig,
        config={
            "displaylogo": False,
            "scrollZoom": True,
            "responsive": True,
            "modeBarButtonsToRemove": ["lasso2d", "select2d"],
        },
        include_plotlyjs=True,
        full_html=True,
        default_width="100%",
        default_height=f"{height}px",
        div_id=div_id,
        post_script=post_script,
    )
    html = html.replace(
        "<head>",
        "<head><style>html,body{margin:0;padding:0;overflow:hidden;background:#08263B;}"
        ".plot-container,.js-plotly-plot{width:100%!important;}</style>",
        1,
    )
    st.iframe(html, width="stretch", height=height, tab_index=0)


def mapa_saude_interativo(
    df: pd.DataFrame,
    key_prefix: str,
    height: int = 720,
    rede_completa: bool = False,
) -> go.Figure:
    """Mapa QA/QC do Complexo Germano, com imagem aérea fixa e detalhes no hover."""
    base = df.dropna(subset=["x", "y"]).copy()

    # O mapa principal deve ser limpo: todos os instrumentos aparecem como pontos,
    # mas apenas os prioritários recebem rótulo permanente. O nome e os demais
    # detalhes continuam disponíveis ao passar o mouse.
    base["rotulo"] = base.apply(
        lambda r: str(r["instrumento"]) if r["status_qaqc"] == "Revisão recomendada" else "", axis=1
    )
    base["situação"] = base["status_qaqc"].map(qaqc_label)
    base["recebimento_exibição"] = base["recebimento"].map(recebimento_label)
    base["sinais_exibição"] = base["motivos"].map(texto_qaqc)

    ordem = ["Revisão recomendada", "Sem atualização recente", "Acompanhar", "Conforme"]
    cores = {
        "Revisão recomendada": "#004071",
        "Sem atualização recente": "#A7B6BF",
        "Acompanhar": "#FFCC00",
        "Conforme": "#95C11F",
    }
    fig = px.scatter(
        base,
        x="x", y="y", color="situação", text="rotulo", hover_name="instrumento",
        hover_data={
            "localidade": True, "natureza": True, "recebimento_exibição": True,
            "sinais_exibição": True, "x": ":.0f", "y": ":.0f", "rotulo": False,
            "situação": False,
        },
        color_discrete_map=cores,
        category_orders={"situação": ordem},
        labels={
            "x": "UTM E (m)", "y": "UTM N (m)", "situação": "Confiabilidade",
            "recebimento_exibição": "Atualização", "sinais_exibição": "Sinais identificados",
            "localidade": "Localidade", "natureza": "Tipo",
        },
    )

    # A imagem aérea de Germano é sempre exibida no mapa principal.
    imagem = carregar_base_aerea()
    if imagem is not None:
        bnd = BASE_AEREA_BOUNDS
        fig.add_layout_image(
            dict(
                source=imagem,
                xref="x", yref="y",
                x=bnd["xmin"], y=bnd["ymax"],
                sizex=bnd["xmax"] - bnd["xmin"],
                sizey=bnd["ymax"] - bnd["ymin"],
                sizing="stretch",
                opacity=0.90,
                layer="below",
                xanchor="left", yanchor="top",
            )
        )

    # Hierarquia visual: alertas ganham mais destaque; pontos OK permanecem discretos.
    tamanho_status = {
        "Revisão recomendada": 13,
        "Sem atualização recente": 11,
        "Acompanhar": 11,
        "Conforme": 9,
    }
    for trace in fig.data:
        trace.update(
            marker=dict(
                size=tamanho_status.get(trace.name, 9),
                line=dict(width=1.5, color="#FFFFFF"),
                opacity=0.98,
            ),
            textposition="top center",
            textfont=dict(size=10, color="#111827", family="Segoe UI Semibold, Segoe UI, Arial"),
            cliponaxis=False,
        )

    _aplicar_cartografia_mapa(
        fig,
        base["x"],
        base["y"],
        rede_completa=rede_completa,
        height=height,
        uirevision=f"{key_prefix}-{'completa' if rede_completa else 'foco'}",
    )
    fig.update_layout(
        legend=dict(
            bgcolor="rgba(0,35,62,0.88)",
            bordercolor="rgba(255,255,255,0.42)", borderwidth=1,
            font=dict(color="#FFFFFF", size=11),
            itemsizing="constant",
            x=.985, y=.975, xanchor="right", yanchor="top",
        ),
    )
    return fig


def mapa_variacao_interativo(
    df_monitor: pd.DataFrame,
    ptr_ativos: pd.DataFrame,
    delta_col: str,
    referencia_col: str,
    height: int = 720,
    rede_completa: bool = False,
) -> go.Figure:
    """Mapa de Δ Cota; mantém em cinza INAs, PZs e PMs sem comparação válida."""
    base = df_monitor.dropna(subset=["x", "y"]).copy()
    base["delta_m"] = pd.to_numeric(base[delta_col], errors="coerce")
    base["referencia_m"] = pd.to_numeric(base[referencia_col], errors="coerce")
    base["atual_m"] = pd.to_numeric(base["cota_atual_representativa_m"], errors="coerce")
    base["delta_exibicao"] = base["delta_m"].map(
        lambda valor: "—" if pd.isna(valor) else f"{numero_pt(valor, sinal=True)} m"
    )
    base["atual_exibicao"] = base["atual_m"].map(
        lambda valor: "—" if pd.isna(valor) else f"{numero_pt(valor)} m"
    )
    base["referencia_exibicao"] = base["referencia_m"].map(
        lambda valor: "—" if pd.isna(valor) else f"{numero_pt(valor)} m"
    )
    base["leitura"] = base["delta_m"].map(classificar_delta)
    validos = base[base["delta_m"].notna()].copy()
    neutros = base[base["delta_m"].isna()].copy()
    limite = max(float(validos["delta_m"].abs().max()), 0.5) if not validos.empty else 1.0

    if validos.empty:
        fig = go.Figure()
    else:
        fig = px.scatter(
            validos,
            x="x", y="y", color="delta_m", hover_name="instrumento",
            hover_data={
                "localidade": True, "delta_exibicao": True,
                "atual_exibicao": True, "referencia_exibicao": True,
                "leitura": True, "delta_m": False, "x": ":.0f", "y": ":.0f",
            },
            color_continuous_scale=[
                [0.0, "#8F2F24"], [0.34, "#D9836C"], [0.5, "#F2F4F5"],
                [0.66, "#79ADD0"], [1.0, "#175A96"],
            ],
            range_color=[-limite, limite],
            labels={
                "x": "UTM E (m)", "y": "UTM N (m)", "delta_m": "Δ Cota (m)",
                "delta_exibicao": "Δ Cota", "localidade": "Setor",
                "atual_exibicao": "Cota atual representativa",
                "referencia_exibicao": "Cota de referência", "leitura": "Comportamento observado",
            },
        )

    if not neutros.empty:
        fig.add_trace(go.Scatter(
            x=neutros["x"], y=neutros["y"], mode="markers", name="INA/PZ/PM sem comparação no período",
            showlegend=False,
            text=neutros["instrumento"],
            customdata=neutros[["localidade", "status_qaqc", "motivos"]],
            marker=dict(symbol="circle", size=9, color="#A7B6BF", line=dict(width=1.4, color="#FFFFFF")),
            hovertemplate=(
                "<b>%{text}</b><br>Localização: %{customdata[0]}<br>Δ Cota: comparação não calculada no período"
                "<br>Confiabilidade: %{customdata[1]}<br>%{customdata[2]}<extra></extra>"
            ),
        ))

    imagem = carregar_base_aerea()
    if imagem is not None:
        bnd = BASE_AEREA_BOUNDS
        fig.add_layout_image(dict(
            source=imagem, xref="x", yref="y", x=bnd["xmin"], y=bnd["ymax"],
            sizex=bnd["xmax"] - bnd["xmin"], sizey=bnd["ymax"] - bnd["ymin"],
            sizing="stretch", opacity=.86, layer="below", xanchor="left", yanchor="top",
        ))

    for trace in fig.data:
        if trace.name != "INA/PZ/PM sem comparação no período":
            trace.update(marker=dict(size=11, line=dict(width=1.4, color="#FFFFFF"), opacity=.96))

    # A geometria identifica o tipo; PTRs nunca participam da escala de Δ Cota.
    fig.add_trace(go.Scatter(
        x=[None], y=[None], mode="markers", name="INA / PZ / PM",
        marker=dict(symbol="circle-open", size=12, color="#FFFFFF", line=dict(width=2, color="#FFFFFF")),
        hoverinfo="skip",
    ))

    mapa_x = base["x"].copy()
    mapa_y = base["y"].copy()
    if not ptr_ativos.empty:
        ptr = ptr_ativos.dropna(subset=["x", "y"]).copy()
        if not ptr.empty:
            mapa_x = pd.concat([mapa_x, ptr["x"]], ignore_index=True)
            mapa_y = pd.concat([mapa_y, ptr["y"]], ignore_index=True)
            fig.add_trace(go.Scatter(
                x=ptr["x"], y=ptr["y"], mode="markers", name="PTR",
                text=ptr["inst_id"],
                marker=dict(symbol="triangle-up", size=13, color="#FFFFFF", line=dict(width=2, color="#004071")),
                customdata=ptr[["localidade"]],
                hovertemplate="<b>%{text}</b><br>Poço tubular ativo<br>Setor: %{customdata[0]}<extra></extra>",
            ))

    _aplicar_cartografia_mapa(
        fig,
        mapa_x,
        mapa_y,
        rede_completa=rede_completa,
        height=height,
        uirevision=f"delta-cota-{'completa' if rede_completa else 'foco'}",
    )
    fig.update_layout(
        coloraxis_colorbar=dict(
            title=dict(text="Δ Cota (m)", font=dict(color="#FFFFFF", size=11)),
            thickness=13,
            len=.52,
            x=.985,
            y=.56,
            bgcolor="rgba(0,35,62,.82)",
            bordercolor="rgba(255,255,255,.42)",
            borderwidth=1,
            tickfont=dict(color="#FFFFFF", size=10),
            outlinecolor="rgba(255,255,255,.65)",
            outlinewidth=1,
        ),
        legend=dict(
            bgcolor="rgba(0,35,62,.88)",
            bordercolor="rgba(255,255,255,.42)", borderwidth=1,
            font=dict(color="#FFFFFF", size=11),
            orientation="h",
            x=.985, y=.975, xanchor="right", yanchor="top",
        ),
    )
    return fig


# -----------------------------------------------------------------------------
# Fonte HGA da sessão
# -----------------------------------------------------------------------------
@st.cache_data(show_spinner=False)
def _bases_padrao_ui():
    hga_source = ROOT / "data" / "HGA-28082026.xlsx"
    hga_cache = ROOT / "data" / "HGA_Germano_UI.pkl.gz"
    source_sha256 = "FB4D457D445AE192177543963A7E4A187676F45E336F779B622F937E9506F176"
    if hga_cache.exists() and hga_source.exists():
        with hga_source.open("rb") as arquivo:
            sha_atual = hashlib.file_digest(arquivo, "sha256").hexdigest().upper()
        if sha_atual == source_sha256:
            cad = pd.read_excel(ROOT / "data" / "Coordenadas.xlsx", sheet_name="Sheet1")
            cad["inst_id"] = cad["TAG HGA"].map(_norm_tag)
            cad = _filtrar_complexo_germano(cad)
            hga = normalizar_hga(pd.read_pickle(hga_cache, compression="gzip"))
            cad = _aplicar_situacao_hga(cad, hga, inferir_data_corte(hga))
            return cad, hga
    return carregar_bases(ROOT / "data")


_HGA_SESSION_KEYS = (
    "hga_upload_active",
    "hga_upload_nome",
    "hga_upload_cad",
    "hga_upload_hga",
    "hga_upload_rede",
    "hga_upload_eventos",
    "hga_upload_data_corte",
    "hga_upload_error",
    "hga_upload_attempt_sha",
)


def _usar_base_padrao():
    for chave in _HGA_SESSION_KEYS:
        st.session_state.pop(chave, None)
    st.session_state.pop("hga_upload_widget", None)
    st.session_state["hga_base_padrao_restaurada"] = True


def _desativar_upload_invalido(sha_arquivo):
    for chave in _HGA_SESSION_KEYS:
        if chave not in {"hga_upload_error", "hga_upload_attempt_sha"}:
            st.session_state.pop(chave, None)
    st.session_state["hga_upload_attempt_sha"] = sha_arquivo
    st.session_state["hga_upload_error"] = MENSAGEM_ARQUIVO_INVALIDO


# -----------------------------------------------------------------------------
# Home, navegação principal e utilidade HGA
# -----------------------------------------------------------------------------
PAGINA_HOME = "Início"
PAGINAS_CONTEUDO = [
    "Resultados",
    "Confiabilidade dos dados",
    "Explorar instrumento",
    "Avaliação técnica",
    "Metodologia",
]
paginas = [PAGINA_HOME, *PAGINAS_CONTEUDO]


def _navegar_para(destino: str) -> None:
    """Atualiza apenas o estado de apresentação; os dados permanecem na sessão."""
    if destino in paginas:
        st.session_state["pagina_ativa"] = destino


def _data_base_hga_texto() -> str:
    if st.session_state.get("hga_upload_active"):
        data_sessao = pd.to_datetime(
            st.session_state.get("hga_upload_data_corte"), errors="coerce"
        )
        if pd.notna(data_sessao):
            return data_sessao.strftime("%d/%m/%Y")
    return "27/08/2026"


def _renderizar_atualizacao_hga(contexto: str) -> bool:
    """Mantém o fluxo validado da v23.5 em uma utilidade visual compacta."""
    with st.container(key=f"hga_update_{contexto}"):
        with st.popover("Atualizar base"):
            st.caption(
                "HGA completa (.xlsx) · uso somente nesta sessão."
            )
            upload_hga = st.file_uploader(
                "Atualizar base HGA",
                type=["xlsx"],
                key="hga_upload_widget",
                help="Aceita somente a planilha .xlsx completa no padrão HGA.",
            )

            if upload_hga is not None:
                conteudo_hga = upload_hga.getvalue()
                sha_upload = hashlib.sha256(conteudo_hga).hexdigest()
                if sha_upload != st.session_state.get("hga_upload_attempt_sha"):
                    with st.spinner("Validando a HGA e atualizando os diagnósticos da sessão..."):
                        try:
                            cadastro_padrao, _ = _bases_padrao_ui()
                            base_processada = processar_upload_hga(
                                conteudo_hga,
                                upload_hga.name,
                                cadastro_padrao,
                            )
                            st.session_state["hga_upload_active"] = True
                            st.session_state["hga_upload_nome"] = upload_hga.name
                            st.session_state["hga_upload_cad"] = base_processada.cadastro
                            st.session_state["hga_upload_hga"] = base_processada.hga
                            st.session_state["hga_upload_rede"] = base_processada.rede
                            st.session_state["hga_upload_eventos"] = base_processada.eventos
                            st.session_state["hga_upload_data_corte"] = base_processada.data_corte
                            st.session_state["hga_upload_attempt_sha"] = sha_upload
                            st.session_state.pop("hga_upload_error", None)
                            st.session_state.pop("hga_base_padrao_restaurada", None)
                        except Exception:
                            _desativar_upload_invalido(sha_upload)
                    st.rerun()

            base_hga_ativa = bool(st.session_state.get("hga_upload_active"))
            if base_hga_ativa:
                corte_upload = pd.to_datetime(
                    st.session_state.get("hga_upload_data_corte"), errors="coerce"
                )
                corte_upload_txt = (
                    corte_upload.strftime("%d/%m/%Y") if pd.notna(corte_upload) else "—"
                )
                st.success(
                    f"Base carregada com sucesso — dados atualizados até {corte_upload_txt}."
                )
            elif st.session_state.get("hga_upload_error"):
                st.error(MENSAGEM_ARQUIVO_INVALIDO)
            elif st.session_state.pop("hga_base_padrao_restaurada", False):
                st.info("Base padrão restaurada.")

            if (
                base_hga_ativa
                or upload_hga is not None
                or st.session_state.get("hga_upload_error")
            ):
                st.button("Usar base padrão", on_click=_usar_base_padrao)
    return bool(st.session_state.get("hga_upload_active"))


def _renderizar_home() -> None:
    rotas = [
        ("01", "Resultados"),
        ("02", "Confiabilidade dos dados"),
        ("03", "Explorar instrumento"),
        ("04", "Avaliação técnica"),
        ("05", "Metodologia"),
    ]
    imagem_uri = image_data_uri(HOME_CAPA)

    coluna_menu, coluna_visual = st.columns([0.88, 1.32], gap="large")
    with coluna_menu:
        st.markdown(
            '<div class="home-grid-intro">'
            '<div class="home-title">Visão geral</div>'
            '</div>',
            unsafe_allow_html=True,
        )
        for _, titulo in rotas:
            chave = titulo.casefold().replace(" ", "_").replace("ç", "c").replace("ã", "a")
            with st.container(key=f"home_nav_{chave}"):
                st.button(
                    titulo,
                    key=f"go_{chave}",
                    use_container_width=True,
                    on_click=_navegar_para,
                    args=(titulo,),
                )

        st.markdown('<div class="home-utility"></div>', unsafe_allow_html=True)
        with st.container(key="home_base_utility"):
            status_col, update_col = st.columns([1.65, 0.82], gap="small")
            with status_col:
                st.markdown(
                    '<div class="home-data-row"><span class="home-data-dot"></span>'
                    f'<span>HGA · atualizada até {_data_base_hga_texto()}</span></div>',
                    unsafe_allow_html=True,
                )
            with update_col:
                _renderizar_atualizacao_hga("home")

    with coluna_visual:
        st.markdown(
            f"""
            <div class="home-visual" style="background-image:url('{imagem_uri}')">
                <div class="home-visual-label">Complexo Germano</div>
                <div class="home-visual-caption">
                    <strong>Complexo Germano</strong>
                    <span>Monitoramento hidrogeológico</span>
                </div>
            </div>
            """,
            unsafe_allow_html=True,
        )


if st.session_state.get("pagina_ativa") not in paginas:
    st.session_state["pagina_ativa"] = PAGINA_HOME

brand_header()

if st.session_state["pagina_ativa"] == PAGINA_HOME:
    _renderizar_home()
    st.stop()

with st.container(key="internal_nav"):
    coluna_navegacao, coluna_atualizacao = st.columns([6.3, 1.0], gap="small")
    with coluna_navegacao:
        pagina = st.segmented_control(
            "Navegação principal",
            paginas,
            selection_mode="single",
            label_visibility="collapsed",
            key="pagina_ativa",
        ) or "Resultados"
    with coluna_atualizacao:
        base_hga_ativa = _renderizar_atualizacao_hga("interno")

aba_resultados = pagina == "Resultados"
aba_avaliacao = pagina == "Avaliação técnica"
aba_inst = pagina == "Explorar instrumento"
aba_qc = pagina == "Confiabilidade dos dados"
aba_metodo = pagina == "Metodologia"

# -----------------------------------------------------------------------------
# Dados
# -----------------------------------------------------------------------------
analise_path = OUT / "analise_delta_cota.csv"
eventos_path = OUT / "qaqc_eventos_atual.csv"

if base_hga_ativa:
    rede = filtrar_germano(st.session_state["hga_upload_rede"].copy())
    eventos = st.session_state["hga_upload_eventos"].copy()
else:
    if not analise_path.exists():
        with st.spinner("Gerando os diagnósticos da rede..."):
            try:
                rodar_analise(ROOT / "data", OUT)
            except Exception:
                st.error("Não foi possível gerar os diagnósticos da base padrão.")
                st.stop()
    rede = filtrar_germano(pd.read_csv(analise_path))
    if eventos_path.exists():
        try:
            eventos = pd.read_csv(eventos_path)
        except pd.errors.EmptyDataError:
            eventos = pd.DataFrame(columns=["instrumento", "data", "cota_na_m", "evento", "magnitude_aprox_m"])
    else:
        eventos = pd.DataFrame(columns=["instrumento", "data", "cota_na_m", "evento", "magnitude_aprox_m"])

rede["localidade"] = rede["localidade"].map(localidade_publica)
for c in ["ultima", "data_corte", "data_referencia_12m", "data_referencia_90d", "salto_data"]:
    if c in rede:
        rede[c] = pd.to_datetime(rede[c], errors="coerce")
for c in ["flatline_ativo", "pos_flatline_pendente", "conflito_recente"]:
    if c in rede:
        rede[c] = rede[c].map(b)
DATA_CORTE = pd.to_datetime(rede["data_corte"], errors="coerce").max()

if not eventos.empty:
    eventos = eventos[eventos["instrumento"].astype(str).isin(rede["instrumento"].astype(str))].copy()
    eventos["data"] = pd.to_datetime(eventos["data"], errors="coerce")


# Catálogo completo de Germano para a página Explorar instrumento.
# Pontos fora de operação permanecem consultáveis com seu histórico.
if base_hga_ativa:
    cad_catalogo_app = st.session_state["hga_upload_cad"].copy()
    hga_catalogo_app = st.session_state["hga_upload_hga"].copy()
else:
    cad_catalogo_app, hga_catalogo_app = _bases_padrao_ui()
ptr_ativos_mapa = cad_catalogo_app[
    (cad_catalogo_app["situacao_operacional"].astype(str).str.strip().str.casefold() == "ativo") &
    (cad_catalogo_app["Natureza do Ponto"] == "Poco Tubular")
].copy()
ptr_ativos_mapa = ptr_ativos_mapa.rename(columns={
    "X(m)": "x", "Y(m)": "y", "Localidade": "localidade",
})
ptr_ativos_mapa["localidade"] = ptr_ativos_mapa["localidade"].map(localidade_publica)

ativos = filtrar_ativos_com_leitura_no_ano(rede, DATA_CORTE)
fisicos = ativos.copy()
instrumentos_nivel = fisicos[
    fisicos["natureza"].astype(str).str.strip().isin(
        ["INA", "Piezometro", "Piezômetro", "Poco Monitoramento", "Poço Monitoramento"]
    )
].copy()
prioritarios = fisicos[fisicos["status_qaqc"] == "Revisão recomendada"].copy()
atencao = fisicos[fisicos["status_qaqc"] == "Acompanhar"].copy()
interrompidos = fisicos[fisicos["status_qaqc"] == "Sem atualização recente"].copy()
ok = fisicos[fisicos["status_qaqc"] == "Conforme"].copy()
recebendo = fisicos[fisicos["recebimento"] == "RECEBENDO"].copy()
n_revisao = len(atencao) + len(interrompidos) + len(prioritarios)

# -----------------------------------------------------------------------------
# Resultados
# -----------------------------------------------------------------------------
if aba_resultados:
    section(
        "Resultados",
        "Resultados",
    )
    if instrumentos_nivel.empty:
        st.info("Não há instrumentos analisados nesta execução.")
    else:
        setores_resultado = sorted(instrumentos_nivel["localidade"].dropna().astype(str).unique().tolist())
        filtro_1, filtro_2 = st.columns(2)
        with filtro_1:
            setor_resultado = st.selectbox("Localização", ["Todos"] + setores_resultado, key="setor_resultados")
        with filtro_2:
            periodo_resultado = st.selectbox(
                "Período de comparação",
                ["12 meses", "90 dias"],
                key="periodo_resultados",
                help=DELTA_COTA_AJUDA,
            )

        periodo_chave = "12m" if periodo_resultado == "12 meses" else "90d"
        delta_col = f"delta_{periodo_chave}_m"
        referencia_col = f"cota_referencia_{periodo_chave}_m"
        data_referencia_col = f"data_referencia_{periodo_chave}"
        classificacao_col = f"classificacao_{periodo_chave}"
        nivel_resultados = instrumentos_nivel.copy()
        ptr_resultados = ptr_ativos_mapa.copy()
        if setor_resultado != "Todos":
            nivel_resultados = nivel_resultados[nivel_resultados["localidade"] == setor_resultado]
            ptr_resultados = ptr_resultados[ptr_resultados["localidade"] == setor_resultado]

        validos = nivel_resultados[nivel_resultados[delta_col].notna()].copy()
        sem_comparacao = nivel_resultados[nivel_resultados[delta_col].isna()].copy()
        sem_cota_atual = int(
            pd.to_numeric(
                sem_comparacao["cota_atual_representativa_m"], errors="coerce"
            ).isna().sum()
        )
        sem_referencia = int(
            (
                pd.to_numeric(
                    sem_comparacao["cota_atual_representativa_m"], errors="coerce"
                ).notna()
                & pd.to_numeric(
                    sem_comparacao[referencia_col], errors="coerce"
                ).isna()
            ).sum()
        )
        contagens = validos[classificacao_col].value_counts()
        kpi_cards([
            ("Ativos no ano", f"{len(nivel_resultados)}", "", "info",
             "Instrumentos ativos com pelo menos uma leitura válida no ano da base."),
            ("Com Δ Cota", f"{len(validos)}", "", "info", DELTA_COTA_AJUDA),
            ("Abaixo", f"{int(contagens.get('Tendência de redução da cota', 0))}", "", "down",
             "Cota atual mais de 0,10 m abaixo da referência do período."),
            ("Estável", f"{int(contagens.get('Comportamento estável', 0))}", "", "ok",
             "Δ Cota entre −0,10 m e +0,10 m."),
            ("Acima", f"{int(contagens.get('Tendência de elevação da cota', 0))}", "", "up",
             "Cota atual mais de 0,10 m acima da referência do período."),
        ])
        if not sem_comparacao.empty:
            st.caption(
                f"{len(sem_comparacao)} sem comparação · {sem_cota_atual} sem cota atual · "
                f"{sem_referencia} sem referência."
            )

        heading_with_help(f"Δ Cota · {periodo_resultado}", DELTA_COTA_AJUDA)
        rede_completa_resultados = st.toggle(
            "Ver rede completa", value=False, key="rede_completa_resultados",
            help="Alterna entre o foco da área principal e a extensão integral dos instrumentos.",
        )
        fig_delta = mapa_variacao_interativo(
            nivel_resultados, ptr_resultados, delta_col, referencia_col,
            height=740, rede_completa=rede_completa_resultados,
        )
        mapa_com_escala_dinamica(fig_delta, key="mapa_resultados_delta", height=740)

        c_reducao, c_elevacao = st.columns(2, gap="large")
        with c_reducao:
            st.markdown("#### Maiores reduções observadas")
            ranking = validos.nsmallest(5, delta_col).copy()
            ranking = ranking[ranking[delta_col] < 0]
            if ranking.empty:
                st.caption("Sem redução com comparação disponível.")
            else:
                ranking.insert(0, "Posição", range(1, len(ranking) + 1))
                ranking[delta_col] = pd.to_numeric(ranking[delta_col], errors="coerce").map(lambda v: numero_pt(v, sinal=True))
                ranking = ranking[["Posição", "instrumento", "localidade", delta_col]]
                ranking.columns = ["#", "Instrumento", "Localização", "Δ Cota (m)"]
                readable_table(ranking, height=275, column_widths=[7, 29, 40, 24], min_width=620)
        with c_elevacao:
            st.markdown("#### Maiores elevações observadas")
            ranking = validos.nlargest(5, delta_col).copy()
            ranking = ranking[ranking[delta_col] > 0]
            if ranking.empty:
                st.caption("Sem elevação com comparação disponível.")
            else:
                ranking.insert(0, "Posição", range(1, len(ranking) + 1))
                ranking[delta_col] = pd.to_numeric(ranking[delta_col], errors="coerce").map(lambda v: numero_pt(v, sinal=True))
                ranking = ranking[["Posição", "instrumento", "localidade", delta_col]]
                ranking.columns = ["#", "Instrumento", "Localização", "Δ Cota (m)"]
                readable_table(ranking, height=275, column_widths=[7, 29, 40, 24], min_width=620)

        with st.expander("Dados da comparação", expanded=False):
            detalhes = nivel_resultados[[
                "instrumento", "localidade", "ultima_leitura_cota_m", "ultima",
                "cota_atual_representativa_m", referencia_col, data_referencia_col, delta_col, "status_qaqc",
            ]].copy()
            for coluna in ["ultima_leitura_cota_m", "cota_atual_representativa_m", referencia_col, delta_col]:
                detalhes[coluna] = pd.to_numeric(detalhes[coluna], errors="coerce").map(
                    lambda valor: numero_pt(valor, sinal=coluna == delta_col)
                )
            detalhes["ultima"] = pd.to_datetime(detalhes["ultima"], errors="coerce").dt.strftime("%d/%m/%Y").fillna("—")
            detalhes[data_referencia_col] = pd.to_datetime(detalhes[data_referencia_col], errors="coerce").dt.strftime("%d/%m/%Y").fillna("—")
            detalhes["status_qaqc"] = detalhes["status_qaqc"].map(qaqc_label)
            detalhes.columns = [
                "Instrumento", "Localização", "Última cota (m)", "Última leitura",
                "Cota atual (m)", "Referência (m)", "Data ref.", "Δ Cota (m)", "Confiabilidade",
            ]
            readable_table(
                detalhes,
                height=480,
                column_widths=[13, 13, 10, 11, 11, 10, 11, 10, 11],
                min_width=980,
            )

# -----------------------------------------------------------------------------
# Confiabilidade dos dados
# -----------------------------------------------------------------------------
if aba_qc:
    section(
        "Confiabilidade",
        "Confiabilidade dos dados",
    )

    kpi_cards([
        ("Ativos", str(len(fisicos)), "", "info",
         "Instrumentos ativos com leitura válida no ano da base."),
        ("Conforme", str(len(ok)), "", "ok",
         "Sem sinal técnico relevante nas verificações atuais de QA/QC."),
        ("Acompanhar", str(len(atencao)), "", "warn",
         "Há um sinal que merece observação, sem invalidar automaticamente o dado."),
        ("Revisão", str(len(prioritarios)), "", "danger",
         "O dado apresenta sinal que requer checagem técnica antes da interpretação."),
        ("Sem atualização", str(len(interrompidos)), "", "info",
         "Não há leitura recente suficiente conforme a cadência do instrumento."),
    ])

    condicionantes_icmbio = rede[rede["instrumento"].map(instrumento_ambiental)].copy()
    if not condicionantes_icmbio.empty:
        quadro_icmbio = condicionantes_icmbio[[
            "instrumento", "ultima", "delta_12m_m", "delta_90d_m", "status_qaqc",
        ]].copy()
        quadro_icmbio["prioridade"] = condicionantes_icmbio.apply(
            classificar_condicionante_icmbio, axis=1
        )
        quadro_icmbio["ultima"] = pd.to_datetime(
            quadro_icmbio["ultima"], errors="coerce"
        ).dt.strftime("%d/%m/%Y").fillna("—")
        for coluna in ["delta_12m_m", "delta_90d_m"]:
            quadro_icmbio[coluna] = pd.to_numeric(
                quadro_icmbio[coluna], errors="coerce"
            ).map(lambda valor: numero_pt(valor, sinal=True))
        quadro_icmbio["status_qaqc"] = quadro_icmbio["status_qaqc"].map(qaqc_label)
        quadro_icmbio.columns = [
            "Instrumento", "Último dado", "Δ 12 meses (m)", "Δ 90 dias (m)", "QA/QC", "Prioridade",
        ]
        with st.expander("Condicionantes ICMBio", expanded=False):
            st.caption(
                "Instrumentos de monitoramento institucional prioritário. "
                "Este destaque não altera o resultado de QA/QC nem o cálculo de Δ Cota."
            )
            readable_table(
                quadro_icmbio,
                height=145,
                column_widths=[20, 15, 15, 15, 15, 20],
                min_width=840,
            )

    heading_with_help("Situação atual da instrumentação", QAQC_AJUDA)
    rede_completa_qaqc = st.toggle(
        "Ver rede completa",
        value=False,
        key="rede_completa_qaqc",
        help="Alterna entre o foco da área principal da mina e a extensão integral dos instrumentos ativos.",
    )
    fig_map = mapa_saude_interativo(
        fisicos,
        "qaqc",
        height=740,
        rede_completa=rede_completa_qaqc,
    )
    mapa_com_escala_dinamica(fig_map, key="mapa_qaqc_v26", height=740)

    heading_with_help(
        f"Instrumentos para acompanhamento · {DATA_CORTE.year}",
        "Reúne Acompanhar, Revisão recomendada e Sem atualização recente. Conforme pode ser incluído em Mostrar todos.",
    )
    fisicos_ativos_qaqc = filtrar_ativos_com_leitura_no_ano(fisicos, DATA_CORTE)
    itens_acompanhamento = fisicos_ativos_qaqc[fisicos_ativos_qaqc["status_qaqc"].isin([
        "Revisão recomendada", "Sem atualização recente", "Acompanhar"
    ])].copy()
    mostrar_todos_qaqc = st.toggle(
        "Mostrar todos",
        value=False,
        key="mostrar_todos_qaqc",
        help="Inclui também os instrumentos classificados como Conforme.",
    )
    show = fisicos_ativos_qaqc.copy() if mostrar_todos_qaqc else itens_acompanhamento
    st.caption(
        f"{len(show)} de {len(fisicos_ativos_qaqc)} instrumentos ativos."
    )
    descricoes_qc = show.apply(
        lambda row: explicar_situacao_instrumento(
            row, "delta_12m_m", "cota_referencia_12m_m", "12 meses"
        ),
        axis=1,
    )
    tab = show[["instrumento", "localidade"]].copy()
    tab["ultimo_dado"] = show.apply(ultimo_dado_publico, axis=1)
    tab[["situacao", "significado", "acao"]] = pd.DataFrame(
        descricoes_qc.tolist(), index=show.index
    )
    tab = tab[["instrumento", "localidade", "ultimo_dado", "situacao"]]
    tab.columns = ["Instrumento", "Localização", "Último dado", "Situação"]
    readable_table(
        tab,
        height=570,
        column_widths=[18, 20, 27, 35],
        min_width=760,
    )
    with st.expander("Detalhes técnicos", expanded=False):
        detalhes_qaqc = fisicos[["instrumento", "natureza", "recebimento", "status_qaqc", "dias_sem_leitura"]].copy()
        detalhes_qaqc["recebimento"] = detalhes_qaqc["recebimento"].map(recebimento_label)
        detalhes_qaqc["status_qaqc"] = detalhes_qaqc["status_qaqc"].map(qaqc_label)
        detalhes_qaqc.columns = ["Instrumento", "Tipo", "Atualização", "Situação", "Dias sem leitura"]
        readable_table(detalhes_qaqc, height=430, column_widths=[22, 16, 20, 25, 17], min_width=760)

# -----------------------------------------------------------------------------
# Instrumentos
# -----------------------------------------------------------------------------
def _hga_ui():
    return hga_catalogo_app

if aba_inst:
    section(
        "Instrumentos",
        "Explorar instrumento",
    )

    with st.spinner("Preparando o catálogo e as séries históricas..."):
        cad_catalogo, _hga_catalogo = cad_catalogo_app, hga_catalogo_app
    catalogo = cad_catalogo[(cad_catalogo["Proposito"] == "Monitoramento Hidrogeologico") &
                            (cad_catalogo["Natureza do Ponto"] != "Cava") &
                            (~cad_catalogo["inst_id"].astype(str).str.contains("PVIRTUAL", case=False, na=False)) &
                            (cad_catalogo["inst_id"].astype(str) != "COTA-NA-REJEITO")].copy()
    catalogo["instrumento"] = catalogo["TAG HGA"].astype(str)

    busca = st.text_input("Buscar instrumento", placeholder="Ex.: 0027-INA-054")
    opcoes = sorted(catalogo["instrumento"].dropna().astype(str).unique().tolist())
    if busca:
        filtradas = [x for x in opcoes if busca.lower() in x.lower()]
    else:
        filtradas = opcoes
    if not filtradas:
        st.info("Nenhum instrumento encontrado.")
    else:
        sel = st.selectbox("Instrumento", filtradas, index=0)
        crow = catalogo[catalogo["instrumento"] == sel].iloc[0]
        qmatch = rede[rede["instrumento"].astype(str) == str(sel)]
        qrow = qmatch.iloc[0] if not qmatch.empty else None

        status_cad = str(crow.get("Situacao Atual", "—") or "—")
        status_op = str(crow.get("situacao_operacional", status_cad) or status_cad)
        ativo_sel = status_op.strip().casefold() == "ativo"
        localidade = localidade_publica(crow.get("Localidade", "—"))
        natureza = str(crow.get("Natureza do Ponto", "—") or "—")

        if qrow is not None:
            qaqc_txt = qaqc_label(qrow.get("status_qaqc", "—"))
            receb_txt = recebimento_label(qrow.get("recebimento", "—"))
            motivo_txt = texto_qaqc(qrow.get("motivos", ""))
        else:
            qaqc_txt = "Consulta histórica"
            receb_txt = "—"
            motivo_txt = "Instrumento disponível somente para consulta histórica."

        prioridade_icmbio = classificar_condicionante_icmbio(qrow) if qrow is not None else "Alerta · sem confirmação"
        flag_icmbio = (
            f'<div class="institutional-flag">Condicionante ICMBio · {html_lib.escape(prioridade_icmbio)}</div>'
            if instrumento_ambiental(sel) else ""
        )
        st.markdown(
            f'<div class="instrument-title"><div class="name">{sel}</div><div class="meta">{localidade} · {natureza}</div><br>'
            f'{status_op} · {qaqc_txt} · {receb_txt}{flag_icmbio}</div>',
            unsafe_allow_html=True,
        )

        with st.expander("Detalhes de confiabilidade", expanded=False):
            st.write(motivo_txt)

        if not ativo_sel:
            st.info("Instrumento fora de operação · histórico disponível para consulta.")
        elif qrow is not None and str(qrow.get("status_qaqc", "")) == "Sem atualização recente":
            ult_txt = pd.to_datetime(qrow.get("ultima"), errors="coerce")
            ult_txt = ult_txt.strftime("%d/%m/%Y") if pd.notna(ult_txt) else "não disponível"
            st.warning(f"Sem atualização recente · último valor em {ult_txt}.")

        if qrow is not None:
            periodo_inst = st.selectbox(
                "Período de comparação",
                ["12 meses", "90 dias"],
                key=f"periodo_instrumento_{normalizar_instrumento(sel)}",
                help=DELTA_COTA_AJUDA,
            )
            periodo_chave_inst = "12m" if periodo_inst == "12 meses" else "90d"
            ref_col_inst = f"cota_referencia_{periodo_chave_inst}_m"
            delta_col_inst = f"delta_{periodo_chave_inst}_m"
            data_ref_col_inst = f"data_referencia_{periodo_chave_inst}"

            ultima_data = pd.to_datetime(qrow.get("ultima"), errors="coerce")
            ultima_data_txt = ultima_data.strftime("%d/%m/%Y") if pd.notna(ultima_data) else "—"
            ultima_cota = pd.to_numeric(qrow.get("ultima_leitura_cota_m"), errors="coerce")
            cota_atual = pd.to_numeric(qrow.get("cota_atual_representativa_m"), errors="coerce")
            cota_ref = pd.to_numeric(qrow.get(ref_col_inst), errors="coerce")
            delta_inst = pd.to_numeric(qrow.get(delta_col_inst), errors="coerce")
            data_ref = pd.to_datetime(qrow.get(data_ref_col_inst), errors="coerce")
            data_ref_txt = data_ref.strftime("%d/%m/%Y") if pd.notna(data_ref) else "—"
            modo_inst = str(qrow.get("modo_monitoramento", "")).casefold()
            ajuda_cota_atual = (
                "Mediana das leituras válidas dos últimos 7 dias, com pelo menos 3 datas e sem sinal impeditivo de consistência."
                if "autom" in modo_inst
                else "Última medição manual válida disponível para o instrumento."
            )

            m1, m2, m3, m4 = st.columns(4)
            m1.metric(
                "Última leitura",
                "—" if pd.isna(ultima_cota) else f"{numero_pt(ultima_cota)} m",
                ultima_data_txt,
                help="Último valor registrado na base, mantido também para consulta histórica.",
            )
            m2.metric(
                "Cota atual representativa",
                "—" if pd.isna(cota_atual) else f"{numero_pt(cota_atual)} m",
                help=ajuda_cota_atual,
            )
            m3.metric(
                f"Referência · {periodo_inst}",
                "—" if pd.isna(cota_ref) else f"{numero_pt(cota_ref)} m",
                data_ref_txt,
                help=REFERENCIA_AJUDA,
            )
            m4.metric(
                "Δ Cota",
                "—" if pd.isna(delta_inst) else f"{numero_pt(delta_inst, sinal=True)} m",
                help=DELTA_COTA_AJUDA,
            )

            ptr = str(qrow.get("ptr_mais_proximo", "") or "").strip()
            dist_ptr = pd.to_numeric(qrow.get("dist_ptr_m"), errors="coerce")
            if ptr and pd.notna(dist_ptr) and natureza != "Poco Tubular":
                st.caption(f"PTR ativo mais próximo: {ptr} · {float(dist_ptr):.0f} m")
            d1, d2, d3, d4 = st.columns(4)
            d1.metric("Monitoramento", str(qrow.get("modo_monitoramento", "—")))
            d2.metric("Data da atualização", ultima_data_txt)
            d3.metric("UTM E", numero_pt(crow.get("X(m)"), casas=0))
            d4.metric("UTM N", numero_pt(crow.get("Y(m)"), casas=0))

        h = _hga_ui()
        import re as _re
        sid = _re.sub(r"\s+", "", str(sel)).upper()
        serie = h[h["inst_id"] == sid].copy()
        fim_snapshot = pd.Timestamp(DATA_CORTE).normalize() + pd.offsets.Day(1)
        serie = serie[(serie["data"].notna()) & (serie["data"] < fim_snapshot) & serie["cota_na_m"].notna()]
        if serie.empty:
            st.warning("Não há série de Cota_NA disponível para este instrumento na HGA atual.")
        else:
            heading_with_help("Série histórica", SERIE_HISTORICA_AJUDA)
            fig_s = px.line(
                serie.sort_values("data"), x="data", y="cota_na_m", color="tipo_dado",
                labels={"data": "Data", "cota_na_m": "Cota do NA (m)", "tipo_dado": "Origem"},
            )
            fig_s.update_traces(mode="lines+markers", marker=dict(size=4))
            if qrow is not None and natureza != "Poco Tubular":
                if pd.notna(cota_atual):
                    fig_s.add_hline(y=float(cota_atual), line_dash="dash", line_color="#176B72", annotation_text="Cota atual representativa")
                if pd.notna(cota_ref):
                    fig_s.add_hline(y=float(cota_ref), line_dash="dot", line_color="#64748B", annotation_text=f"Referência · {periodo_inst}")
            if qrow is not None and not eventos.empty:
                evs = eventos[(eventos["instrumento"].astype(str) == sel)].dropna(subset=["data", "cota_na_m"])
                if not evs.empty:
                    fig_s.add_trace(go.Scatter(
                        x=evs["data"], y=evs["cota_na_m"], mode="markers",
                        name="Ponto para avaliação técnica", marker=dict(size=11, symbol="x", color="#FFCC00", line=dict(width=1, color="#004071")),
                        text=evs["evento"], hovertemplate="%{text}<br>%{x|%d/%m/%Y}<br>%{y:.2f} m<extra></extra>"
                    ))
            plot_clean(fig_s, 520)
            st.plotly_chart(fig_s, width="stretch")

    st.download_button(
        "Exportar confiabilidade dos ativos",
        data=rede.to_csv(index=False).encode("utf-8-sig"),
        file_name="HidroCheck_confiabilidade_ativos.csv",
        mime="text/csv",
    )

# -----------------------------------------------------------------------------
# Avaliação técnica
# -----------------------------------------------------------------------------
if aba_avaliacao:
    section(
        "Avaliação técnica",
        "Avaliação técnica",
    )

    if instrumentos_nivel.empty:
        st.info("A avaliação técnica ainda não está disponível nesta execução.")
    else:
        # A síntese executiva representa a rede em operação com evidência de
        # medição válida no ano do snapshot.
        avaliacao = filtrar_ativos_com_leitura_no_ano(instrumentos_nivel, DATA_CORTE)
        setores = sorted(avaliacao["localidade"].dropna().astype(str).unique().tolist())
        f1, f2 = st.columns(2)
        with f1:
            setor_sel = st.selectbox("Localização", ["Todos"] + setores, key="setor_avaliacao")
        with f2:
            periodo_avaliacao = st.selectbox(
                "Período de comparação",
                ["12 meses", "90 dias"],
                key="periodo_avaliacao",
                help=DELTA_COTA_AJUDA,
            )
        if setor_sel != "Todos":
            avaliacao = avaliacao[avaliacao["localidade"] == setor_sel]

        chave_avaliacao = "12m" if periodo_avaliacao == "12 meses" else "90d"
        delta_av = f"delta_{chave_avaliacao}_m"
        classe_av = f"classificacao_{chave_avaliacao}"
        dif_viz_av = f"diferenca_vizinhos_{chave_avaliacao}_m"
        validos_av = avaliacao[avaliacao[delta_av].notna()].copy()
        kpi_cards([
            ("Abaixo", str(int((pd.to_numeric(validos_av[delta_av], errors="coerce") < -0.10).sum())), "", "down",
             "Cota atual mais de 0,10 m abaixo da referência do período."),
            ("Acima", str(int((pd.to_numeric(validos_av[delta_av], errors="coerce") > 0.10).sum())), "", "up",
             "Cota atual mais de 0,10 m acima da referência do período."),
            ("Acompanhar", str(int(avaliacao["status_qaqc"].eq("Acompanhar").sum())), "", "warn",
             "Há um sinal que merece observação, sem invalidar automaticamente o dado."),
            ("Sem atualização", str(int(avaliacao["status_qaqc"].eq("Sem atualização recente").sum())), "", "info",
             "Não há leitura recente suficiente conforme a cadência do instrumento."),
        ])

        referencia_av = f"cota_referencia_{chave_avaliacao}_m"
        descricoes = avaliacao.apply(
            lambda row: explicar_situacao_instrumento(
                row, delta_av, referencia_av, periodo_avaliacao
            ),
            axis=1,
        )
        avaliacao[["situacao_didatica", "significado_didatico", "acao_didatica"]] = pd.DataFrame(
            descricoes.tolist(), index=avaliacao.index
        )
        avaliacao["ultimo_dado_publico"] = avaliacao.apply(ultimo_dado_publico, axis=1)
        avaliacao["ordem_tecnica"] = avaliacao["status_qaqc"].map({
            "Sem atualização recente": 0, "Acompanhar": 1, "Revisão recomendada": 2, "Conforme": 3,
        }).fillna(4)
        avaliacao["magnitude_delta"] = pd.to_numeric(avaliacao[delta_av], errors="coerce").abs().fillna(-1)
        avaliacao = avaliacao.sort_values(["ordem_tecnica", "magnitude_delta"], ascending=[True, False])

        st.markdown(f"#### Instrumentos ativos · {DATA_CORTE.year}")
        tab_resumo = avaliacao[[
            "instrumento", "localidade", "ultimo_dado_publico", delta_av,
            "situacao_didatica"
        ]].copy()
        tab_resumo[delta_av] = pd.to_numeric(tab_resumo[delta_av], errors="coerce").map(lambda v: numero_pt(v, sinal=True))
        tab_resumo.columns = [
            "Instrumento", "Localização", "Último dado", "Δ Cota (m)", "Situação",
        ]
        readable_table(
            tab_resumo,
            height=570,
            column_widths=[17, 18, 25, 13, 27],
            min_width=820,
        )

        with st.expander("Ver contexto espacial e operacional", expanded=False):
            tab_contexto = avaliacao[[
                "instrumento", "localidade", delta_av, dif_viz_av, "ptr_mais_proximo", "dist_ptr_m"
            ]].copy()
            tab_contexto[delta_av] = pd.to_numeric(tab_contexto[delta_av], errors="coerce").map(lambda v: numero_pt(v, sinal=True))
            tab_contexto[dif_viz_av] = pd.to_numeric(tab_contexto[dif_viz_av], errors="coerce").map(lambda v: numero_pt(v, sinal=True))
            tab_contexto["dist_ptr_m"] = pd.to_numeric(tab_contexto["dist_ptr_m"], errors="coerce").map(numero_pt)
            tab_contexto.columns = [
                "Instrumento", "Localização", "Δ Cota (m)", "Diferença para vizinhos (m)",
                "PTR ativo mais próximo", "Distância (m)",
            ]
            readable_table(tab_contexto, height=520, column_widths=[17, 17, 13, 19, 20, 14], min_width=900)

# -----------------------------------------------------------------------------
# Metodologia
# -----------------------------------------------------------------------------
if aba_metodo:
    section(
        "Rastreabilidade",
        "Metodologia",
    )

    st.markdown(
        """
        <div class="flow">
            <div class="flow-step"><div class="num">1</div><b>Snapshot</b><span>Última leitura válida da base.</span></div>
            <div class="flow-step"><div class="num">2</div><b>Preparação</b><span>Registros válidos e horários consistentes.</span></div>
            <div class="flow-step"><div class="num">3</div><b>Cota atual</b><span>Valor representativo por regime de aquisição.</span></div>
            <div class="flow-step"><div class="num">4</div><b>Comparação</b><span>Cota atual menos referência.</span></div>
            <div class="flow-step"><div class="num">5</div><b>Contexto</b><span>QA/QC, vizinhança e PTR.</span></div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    criterios = pd.DataFrame([
        ["Cota atual · automático", "Mediana dos últimos 7 dias, com ao menos 3 datas válidas e consistentes"],
        ["Cota atual · manual", "Última medição manual válida"],
        ["Referência · automático", "Trecho consistente próximo da data-alvo · tolerância de ±14 dias"],
        ["Referência · manual", "Medição válida mais próxima da data-alvo · tolerância de ±30 dias"],
        ["Δ Cota", "Cota atual representativa − cota de referência"],
        ["Flatline automático", "Mesmo valor em pelo menos 5 datas consecutivas"],
        ["Mudança recente", "Avaliação adaptativa pelas diferenças do instrumento"],
        ["Atualização", "Automáticos: 5 dias · manuais: limite compatível com a cadência"],
        ["Mapas", "Variação e confiabilidade em visualizações separadas"],
        ["Histórico", "Série integral disponível para consulta"],
    ], columns=["Regra", "Critério"])
    readable_table(criterios, height=410, column_widths=[28, 72], min_width=680)
    st.caption(
        "Apoio à análise técnica · sem diagnóstico causal · PTR como contexto. "
        f"Snapshot: {pd.Timestamp(DATA_CORTE).strftime('%d/%m/%Y')}."
    )

